import express from "express";
import { z } from "zod";
import Thread from "../models/Thread.js";
import getLLMResponse from "../utils/llm.js";
import ownerFilter from "../middleware/ownerFilter.js";

const router = express.Router();

// ── Zod schemas ──────────────────────────────────────────────────────────────

// UUID v4 pattern (generated by crypto.randomUUID on the frontend)
const uuidSchema = z.string().uuid("threadId must be a valid UUID");

const chatSchema = z.object({
    threadId: uuidSchema,
    message: z.string()
               .min(1, "Message cannot be empty")
               .max(4000, "Message cannot exceed 4000 characters")
               .trim()
});

// ── GET /thread – list all threads for the current owner ─────────────────────
// Supports cursor-based pagination: pass ?limit=20&cursor=<updatedAt ISO string>
// Returns only { threadId, title, updatedAt } to keep the payload small.

router.get("/thread", async (req, res, next) => {
    try {
        const owner = ownerFilter(req); // throws 403 if no identifier

        const limit = Math.min(parseInt(req.query.limit) || 20, 100);
        const cursor = req.query.cursor; // ISO date string of the last item seen

        const query = { ...owner };
        // Cursor pagination: fetch threads older than the cursor
        if (cursor) {
            const cursorDate = new Date(cursor);
            if (!isNaN(cursorDate)) {
                query.updatedAt = { $lt: cursorDate };
            }
        }

        const threads = await Thread
            .find(query)
            .sort({ updatedAt: -1 })
            .limit(limit)
            .select("threadId title updatedAt");

        res.json(threads);
    } catch (error) {
        next(error);
    }
});

// ── GET /thread/:threadId – load messages for a specific thread ──────────────

router.get("/thread/:threadId", async (req, res, next) => {
    const parsed = uuidSchema.safeParse(req.params.threadId);
    if (!parsed.success) {
        return res.status(400).json({ error: parsed.error.issues[0].message });
    }

    try {
        const owner = ownerFilter(req);
        // Scope by both threadId AND owner — wrong owner gets a 404, not a 403,
        // to avoid revealing that the thread exists.
        const thread = await Thread.findOne({ threadId: req.params.threadId, ...owner });
        if (!thread) {
            return res.status(404).json({ error: "Thread not found" });
        }
        res.json(thread.messages);
    } catch (error) {
        next(error);
    }
});

// ── DELETE /thread/:threadId – delete a thread owned by the caller ───────────

router.delete("/thread/:threadId", async (req, res, next) => {
    const parsed = uuidSchema.safeParse(req.params.threadId);
    if (!parsed.success) {
        return res.status(400).json({ error: parsed.error.issues[0].message });
    }

    try {
        const owner = ownerFilter(req);
        const deleted = await Thread.findOneAndDelete({
            threadId: req.params.threadId,
            ...owner
        });
        if (!deleted) {
            return res.status(404).json({ error: "Thread not found" });
        }
        res.json({ success: "Thread deleted successfully" });
    } catch (error) {
        next(error);
    }
});

// ── POST /chat – send a message and receive an LLM reply ─────────────────────

router.post("/chat", async (req, res, next) => {
    const parsed = chatSchema.safeParse(req.body);
    if (!parsed.success) {
        return res.status(400).json({ error: parsed.error.issues[0].message });
    }

    const { threadId, message } = parsed.data;

    try {
        const owner = ownerFilter(req);

        let thread = await Thread.findOne({ threadId, ...owner });

        if (!thread) {
            // Create a new thread scoped to this owner only
            thread = new Thread({
                threadId,
                ...owner, // sets either userId or guestId
                title: message.slice(0, 40),
                messages: [{ role: "user", content: message }]
            });
        } else {
            thread.messages.push({ role: "user", content: message });
        }

        // Send full conversation history so the LLM has multi-turn context
        const assistantReply = await getLLMResponse(thread.messages);
        thread.messages.push({ role: "assistant", content: assistantReply });
        await thread.save();

        res.json({ reply: assistantReply });
    } catch (error) {
        next(error);
    }
});

export default router;
